scripts.lcg_counter:
def solve(inputs: dict) -> float:
    X = inputs['SEED']  # Starting value
    A = inputs['A']     # Multiplier
    B = inputs['B']     # Increment
    M = inputs['M']     # Modulus
    K = inputs['K']     # Number of rounds

    # Run K rounds of the LCG
    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

scripts.alternating_sum:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Compute alternating sum: +v[0] -v[1] +v[2] -v[3] ...
    result = 0
    for i, val in enumerate(values):
        if i % 2 == 0:
            result += val
        else:
            result -= val

    return float(result)

